import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Inline C++ declaration
layer_norm_cpp = r"""
torch::Tensor layer_norm_forward_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps
);
"""

# Inline CUDA code with two kernels for (1) computing mean/var, and (2) applying LN
layer_norm_cuda = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Kernel 1: compute partial sums of x and x^2 for each batch element
__global__ void compute_sums_kernel(
    const float* __restrict__ x,
    float* __restrict__ sum_x,
    float* __restrict__ sum_x2,
    int batch_size,
    int num_features)
{
    // Each thread handles one element in x
    // x has shape [batch_size, num_features].
    // sum_x and sum_x2 each have shape [batch_size].
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * num_features) return;

    int b = idx / num_features;
    float val = x[idx];
    atomicAdd(&sum_x[b], val);
    atomicAdd(&sum_x2[b], val * val);
}

// Kernel 2: apply normalization
__global__ void layer_norm_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ sum_x,
    const float* __restrict__ sum_x2,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float eps,
    int batch_size,
    int num_features)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * num_features) return;

    int b = idx / num_features;
    float mean = sum_x[b] / num_features;
    float var = sum_x2[b] / num_features - mean * mean;
    float r_std = rsqrtf(var + eps);

    // element index within [0, num_features)
    int feat_idx = idx % num_features;
    float norm_val = (x[idx] - mean) * r_std;
    y[idx] = norm_val * gamma[feat_idx] + beta[feat_idx];
}

// Forward function to handle layer normalization
torch::Tensor layer_norm_forward_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps)
{
    // x shape: [B, ...], flatten to [B, num_features] so LN is over last dimensions
    // gamma, beta shape: [num_features]
    // We'll treat everything after batch as "features".
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be a CUDA tensor");
    TORCH_CHECK(beta.is_cuda(), "beta must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat, "x must be float tensor");
    TORCH_CHECK(gamma.dtype() == torch::kFloat, "gamma must be float tensor");
    TORCH_CHECK(beta.dtype() == torch::kFloat, "beta must be float tensor");

    // Flatten the input except for the first dimension
    auto shape = x.sizes();
    int batch_size = shape[0];
    long num_features = 1;
    for (int i = 1; i < shape.size(); i++) {
        num_features *= shape[i];
    }

    // Create a view for easier kernel dispatch
    auto x_2d = x.view({batch_size, num_features});

    // Allocate sum arrays for each batch element
    auto sum_x = torch::zeros({batch_size}, x.options());
    auto sum_x2 = torch::zeros({batch_size}, x.options());

    // Launch kernel to compute sums
    int threads = 256;
    int blocks = (batch_size * num_features + threads - 1) / threads;
    compute_sums_kernel<<<blocks, threads>>>(
        x_2d.data_ptr<float>(),
        sum_x.data_ptr<float>(),
        sum_x2.data_ptr<float>(),
        batch_size,
        num_features
    );

    // Prepare output
    auto y = torch::empty_like(x);
    auto y_2d = y.view({batch_size, num_features});

    // Launch kernel to apply LN
    layer_norm_kernel<<<blocks, threads>>>(
        x_2d.data_ptr<float>(),
        y_2d.data_ptr<float>(),
        sum_x.data_ptr<float>(),
        sum_x2.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        eps,
        batch_size,
        num_features
    );

    return y;
}
"""

layer_norm_ext = load_inline(
    name="layer_norm_ext",
    cpp_sources=layer_norm_cpp,
    cuda_sources=layer_norm_cuda,
    functions=["layer_norm_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model performing Layer Normalization via a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5):
        super(ModelNew, self).__init__()
        # Match behavior of nn.LayerNorm with elementwise affine
        self.gamma = nn.Parameter(torch.ones(normalized_shape, dtype=torch.float))
        self.beta = nn.Parameter(torch.zeros(normalized_shape, dtype=torch.float))
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Flatten gamma/beta to 1D for the kernel (same total number of elements)
        flat_gamma = self.gamma.view(-1).contiguous()
        flat_beta = self.beta.view(-1).contiguous()
        return layer_norm_ext.layer_norm_forward_cuda(x, flat_gamma, flat_beta, self.eps)

